          "error",
        );
      }
    },
    [key, notify],
  )

useEffect(() => {
    const timer = setTimeout(() => persist(draft), 180);
    return () => clearTimeout(timer);
  }, [draft, persist])

useEffect(() => {
    if (prompt) {
      setDraft((previous) => ({ ...previous, text: prompt }));
      clearPrompt();
    }
  }, [prompt, clearPrompt])

useEffect(() => {
    const input = inputRef.current;
    if (input) {
      input.style.height = "auto";
      input.style.height = Math.min(input.scrollHeight, 220) + "px";
    }
  }, [draft.text, inputRef])

return (
    <div className="composer-dock">
      <div className="composer-width">
        {!ready && (
          <div className="provider-hint">
            <Sparkles size={13} />
            <span>Choose a model to bring your agent online.</span>
            <button onClick={onConfigure}>
              Set up model
              <ArrowUp size={12} />
            </button>
          </div>
        )}
        <div className={"composer-box " + (draft.pending ? "has-pending" : "")}>
          <Textarea
            ref={inputRef}
            aria-label="Message"
            placeholder="Ask anything, or pick up where you left off…"
            value={draft.text}
            onChange={(event) =>
              setDraft((previous) => ({
                ...previous,
                text: event.target.value,
              }))
            }
            onKeyDown={(event) => {
              if (
                event.key === "Enter" &&
                !event.shiftKey &&
                !event.nativeEvent.isComposing
              ) {
                event.preventDefault();
                send();
              }
            }}
          />
          {draft.attachments.length > 0 && (
            <div className="attachment-chips">
              {draft.attachments.map((a) => (
                <span key={a.id}>
                  <FileText size={12} />
                  {a.name}
                  <button
                    aria-label={"Remove " + a.name}
                    onClick={() =>
                      setDraft((previous) => ({
                        ...previous,
                        attachments: previous.attachments.filter(
                          (item) => item.id !== a.id,
                        ),
                      }))
                    }
                  >
                    <X size={12} />
                  </button>
                </span>
              ))}
            </div>
          )}
          <div className="composer-controls">
            <div className="row">
              <Tooltip label="Attach a source">
                <Button
                  variant="ghost"
