  candidate: { action: string | { text?: string } };
};

type WorkData = {
  goals: Goal[];
  commitments: Commitment[];
  schedules: Schedule[];
  workflows: Workflow[];
  work: Work[];
  children: Work[];
  inbox: Proposal[];
};

type Editor = {
  kind: "goal" | "commitment" | "schedule" | "workflow";
  goal?: Goal;
} | null;

