return (
    <details className="wc-budget">
      <summary>Compute allowance</summary>
      <p className="field-hint">
        Maximum resources this work may use. Actual consumption stays visible in
        Settings.
      </p>
      <div className="form-row">
        <label className="field">
          Tokens
          <Input
            type="number"
            name="tokens"
            min={1}
            step={1}
            defaultValue={tokens}
            required
          />
        </label>
        <label className="field">
          Model turns
          <Input
            type="number"
            name="iterations"
            min={1}
            max={256}
            step={1}
            defaultValue={iterations}
            required
          />
        </label>
        <label className="field">
          Time in seconds
          <Input
            type="number"
            name="seconds"
            min={1}
            max={86400}
            step={1}
            defaultValue={seconds}
            required
          />
        </label>
        <label className="field">
          Tool calls
          <Input
            type="number"
            name="tool_calls"
            min={0}
            max={10000}
            step={1}
            defaultValue={calls}
            required
          />
        </label>
      </div>
    </details>
  );

return {
    tokens: Number(data.get("tokens")),
    iterations: Number(data.get("iterations")),
    elapsed_ms: Number(data.get("seconds")) * 1000,
    tool_calls: Number(data.get("tool_calls")),
  };

