facts.source:
if (query.isPending)
    content = (
      <div className="stack">
        <Skeleton className="h-24" />
        <Skeleton className="h-64" />
      </div>
    );
  else if (query.error || !data)
    content = (
      <div className="page-error">
        <h2>Work could not be loaded</h2>
        <p>{query.error?.message}</p>
        <Button onClick={() => query.refetch()}>Try again</Button>
      </div>
    );
  else if (tab === "Goals")
    content = (
      <Card
        title="The outcomes that matter"
        description="Activate a goal deliberately. Completion remains tied to evidence."
      >
        {goals.length ? (
          goals.map((goal) => (
            <WorkRow
              key={goal.id}
              icon={<Target size={18} />}
              title={goal.objective}
              state={goal.state}
              actions={
                <>
                  {[
                    "proposed",
                    "paused",
                    "waiting",
                    "reviewing",
                    "blocked",
                  ].includes(goal.state) && (
                    <Button
                      size="sm"
                      disabled={pending}
                      onClick={() =>
                        execute(
                          "goals.transition",
                          {
                            id: goal.id,
                            state: "active",
                            expected_revision: goal.revision,
                          },
                          "Goal activated.",
                        )
                      }
                    >
                      <Play size={13} />
                      {goal.state === "proposed"
                        ? "Activate goal"
                        : "Resume goal"}
                    </Button>
                  )}
                  {goal.state === "active" && (
                    <Button
                      size="sm"
                      disabled={pending}
                      onClick={() =>
                        execute(
                          "goals.transition",
                          {
                            id: goal.id,
                            state: "paused",
                            expected_revision: goal.revision,
                          },
                          "Goal paused.",
                        )
                      }
                    >
                      <Pause size={13} />
                      Pause goal
                    </Button>
                  )}
                  {!terminalGoals.has(goal.state) && (
                    <>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => open({ kind: "goal", goal })}
                      >
                        Edit goal
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        disabled={pending}
                        onClick={() =>
                          execute(
                            "goals.transition",
                            {
                              id: goal.id,
                              state: "abandoned",
                              expected_revision: goal.revision,
                              reason: "Owner ended this goal",
                            },
                            "Goal abandoned; future execution is fenced.",
                          )
                        }
                      >
                        Abandon goal
                      </Button>
                    </>
                  )}
                  {terminalGoals.has(goal.state) && (
                    <Button
                      size="sm"
                      variant="ghost"
                      disabled={pending}
                      onClick={() =>
                        execute(
                          "goals.archive",
                          { id: goal.id, expected_revision: goal.revision },
                          "Goal archived.",
                        )
                      }
                    >
                      Archive goal
                    </Button>
                  )}
                </>
              }
            >
              <Evidence value={goal} />
            </WorkRow>
          ))
        ) : (
          <EmptyState
            icon={<Target />}
            title="Give your work a direction"
            description="A goal holds the outcome you care about, its resource allowance, and the evidence of progress."
            action={
              <Button onClick={() => open({ kind: "goal" })}>
                Create a goal
              </Button>
            }
          />
        )}
      </Card>
    );
  else if (tab === "Commitments")
    content = (
      <Card
        title="Accepted responsibilities"
        description="A proposed responsibility becomes a commitment when you accept it."
      >
        {data.commitments.length ? (
          data.commitments.map((commitment) => (
            <WorkRow
              key={commitment.id}
              icon={<Flag size={18} />}
              title={commitment.description}
              state={commitment.state}
              subtitle={`${titleCase(commitment.progress)} · For ${commitment.beneficiary}`}
              actions={
                <>
                  {commitment.state === "proposed" && (
                    <Button
                      size="sm"
                      disabled={pending}
                      onClick={() =>
                        execute(
                          "commitments.transition",
                          {
                            id: commitment.id,
                            state: "accepted",
                            expected_revision: commitment.revision,
                          },
                          "Commitment accepted.",
                        )
                      }
                    >
                      <Check size={13} />
                      Accept commitment
                    </Button>
                  )}
                  {commitment.state === "accepted" && !commitment.wait_id && (
                    <Button
                      size="sm"
                      disabled={pending}
                      onClick={() =>
                        execute(
                          "commitments.progress",
                          {
                            id: commitment.id,
                            progress:
                              commitment.progress === "blocked"
                                ? "in_progress"
                                : "blocked",
                            expected_revision: commitment.revision,
                            reason: "Owner updated responsibility progress",
                          },
                          "Progress updated.",
                        )
                      }
                    >
                      {commitment.progress === "blocked"
                        ? "Mark in progress"
                        : "Mark blocked"}
                    </Button>
                  )}
                  {["proposed", "accepted"].includes(commitment.state) && (
                    <Button
                      variant="ghost"
                      size="sm"
                      disabled={pending}
                      onClick={() =>
                        execute(
                          "commitments.transition",
                          {
                            id: commitment.id,
                            state: "cancelled",
                            expected_revision: commitment.revision,
                            reason: "Owner released this responsibility",
                          },
                          "Commitment cancelled.",
                        )
                      }
                    >
                      Cancel commitment
                    </Button>
                  )}
                </>
              }
            >
              <Evidence value={commitment} />
            </WorkRow>
          ))
        ) : (
          <EmptyState
            icon={<Flag />}
            title="Clear promises. Visible progress."
            description="Keep responsibilities explicit, including who they are for and what is still waiting."
          />
        )}
      </Card>
    );
  else if (tab === "Schedules")
    content = (
      <Card
        title="A place in time"
        description="Scheduled prompts return to their conversation with their own compute allowance."
      >
        {data.schedules.length ? (
          data.schedules.map((schedule) => (
            <WorkRow
              key={schedule.id}
              icon={<CalendarClock size={18} />}
              title={schedule.payload.text || "Scheduled prompt"}
              state={schedule.state}
              subtitle={
                schedule.next_due
                  ? "Next run · " +
                    new Date(schedule.next_due * 1000).toLocaleString()
                  : "No upcoming run"
              }
              actions={
                <>
                  {["active", "paused"].includes(schedule.state) && (
                    <>
                      <Button
                        size="sm"
                        disabled={pending}
                        onClick={() =>
                          execute(
                            "schedules.state",
                            {
                              id: schedule.id,
                              state:
                                schedule.state === "active"
                                  ? "paused"
                                  : "active",
                              expected_revision: schedule.revision,
                            },
                            "Schedule updated.",
                          )
                        }
                      >
                        {schedule.state === "active" ? (
                          <Pause size={13} />
                        ) : (
                          <Play size={13} />
                        )}
                        {schedule.state === "active"
                          ? "Pause schedule"
                          : "Resume schedule"}
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        disabled={pending}
                        onClick={() =>
                          execute(
                            "schedules.state",
                            {
                              id: schedule.id,
                              state: "cancelled",
                              expected_revision: schedule.revision,
                            },
                            "Schedule cancelled.",
                          )
                        }
                      >
                        Cancel schedule
                      </Button>
                    </>
                  )}
                </>
              }
            >
              <Evidence value={schedule} />
            </WorkRow>
          ))
        ) : (
          <EmptyState
            icon={<CalendarClock />}
            title="Let the right work find its moment"
            description="Schedule a one-time prompt or a repeating check-in. You decide when and how much it may use."
            action={
              <Button onClick={() => open({ kind: "schedule" })}>
                Schedule prompt
              </Button>
            }
          />
        )}
      </Card>
    );
  else if (tab === "Workflows")
    content = (
      <Card
        title="One step makes the next possible"
        description="Dependencies run through the agent’s scheduler. Each result retains its evidence."
      >
        {data.workflows.length ? (
          data.workflows.map((plan) => (
            <WorkRow
              key={plan.id}
              icon={<GitBranch size={18} />}
              title={plan.steps[0]?.description || "Workflow"}
              state={plan.state}
              subtitle={`${plan.steps.filter((step) => step.state === "completed").length} of ${plan.steps.length} steps complete`}
              actions={
                <>
                  {plan.state === "active" && (
                    <>
                      <Button
                        size="sm"
                        disabled={pending}
                        onClick={() => runWorkflow(plan)}
                      >
                        <Play size={13} />
                        Run workflow
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        disabled={pending}
                        onClick={() =>
                          execute(
                            "workflows.state",
                            {
                              id: plan.id,
                              state: "paused",
                              expected_revision: plan.revision,
                              reason: "Owner paused workflow",
                            },
                            "Workflow paused.",
                          )
                        }
                      >
                        Pause workflow
                      </Button>
                    </>
                  )}
                  {plan.state === "paused" && (
                    <Button
                      size="sm"
                      disabled={pending}
                      onClick={() =>
                        execute(
                          "workflows.state",
                          {
                            id: plan.id,
                            state: "active",
                            expected_revision: plan.revision,
                          },
                          "Workflow resumed. Choose Run to continue.",
                        )
                      }
                    >
                      <Play size={13} />
                      Resume workflow
                    </Button>
                  )}
                </>
              }
            >
              <ol className="wc-steps">
                {plan.steps.map((step) => (
                  <li key={step.id}>
                    <span
                      className={
                        step.state === "completed" ? "wc-step-done" : ""
                      }
                    >
                      {step.state === "completed" ? (
                        <Check size={12} />
                      ) : (
                        <Circle size={9} />
                      )}
                    </span>
                    <span>{step.description}</span>
                    <small>{titleCase(step.state)}</small>
                  </li>
                ))}
              </ol>
              <Evidence value={plan} />
            </WorkRow>
          ))
        ) : (
          <EmptyState
            icon={<GitBranch />}
            title="Build a little momentum"
            description="Turn a larger task into dependent steps. Narrative completion and observed world outcomes remain distinct."
            action={
              <Button onClick={() => open({ kind: "workflow" })}>
