            <div>
              <strong>{live.length}</strong>
              <span>Work in motion</span>
            </div>
          </div>
        </div>
        <Card
          title="Agent activity"
          description="Recent work and its recorded outcomes."
        >
          {data.work.length ? (
            data.work.map((work) => (
              <WorkRow
