      { id: "room", title: "Research thread", revision: 4, archived: false },
    ],
    reject = true;
  const changes: Record<string, unknown>[] = [];
  const page = mount({
    handlers: {
      "conversations.list": () => ({ items: rooms }),
      "conversations.update": (params) => {
        changes.push(params);
